/**
 *
 * TreeLoading renders a loading overlay over the tree while `Tree.Root.loading` is true.
 *
 * @module TreeLoading
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TreeRootInstance } from './TreeRoot.types';
/**
 * Defines passthrough(pt) options type in TreeLoading component.
 */
export type TreeLoadingPassThroughType<E> = PassThroughType<TreeLoadingInstance, E>;
/**
 * Defines passthrough(pt) options of TreeLoading component.
 */
export interface TreeLoadingPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TreeLoadingPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in TreeLoading component.
 */
export interface TreeLoadingProps extends BaseComponentProps<TreeLoadingInstance, unknown, TreeLoadingPassThrough> {
}
/**
 * Defines valid state in TreeLoading component.
 */
export interface TreeLoadingState {
}
/**
 * Defines the methods and properties exposed by TreeLoading component.
 */
export interface TreeLoadingExposes {
    /**
     * The Tree component instance.
     */
    tree: TreeRootInstance | undefined | null;
}
/**
 * Instance of TreeLoading component.
 */
export type TreeLoadingInstance = ComponentInstance<TreeLoadingProps, TreeLoadingState, TreeLoadingExposes>;
